-- PROPOSED ONLY: depends on 009, 010, 011. Never applied by approved eight-file migrations.
-- Extends existing invoices, receipts, cheques, statements and ONE accounting-entry ledger.
-- No original transaction/role assignment is rewritten or deleted.
INSERT INTO ab.permissions(id) SELECT 'ledger_'||unnest(ARRAY['view','invoice_create','invoice_correct','invoice_import','collect','collection_override','hand_over','receive','deposit','deposit_verify','fund_manage','petty_spend','voucher_create','voucher_approve','voucher_batch','voucher_cancel','cheques','settle','journal_create','journal_approve','account_manage','item_manage','statement_upload','reconcile','close','group_close','report','export','configure','cards','card_settle','intercompany','audit']) ON CONFLICT DO NOTHING;
CREATE TABLE ab.finance_accounts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,code text NOT NULL,name_ar text NOT NULL,name_en text NOT NULL,kind text NOT NULL CHECK(kind IN('asset','liability','equity','income','expense')),parent_id uuid,active boolean NOT NULL DEFAULT true,eliminate boolean NOT NULL DEFAULT false,cash_flow text CHECK(cash_flow IN('operating','investing','financing')),UNIQUE(tenant_id,code),FOREIGN KEY(tenant_id,parent_id)REFERENCES ab.finance_accounts(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_items(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,code text NOT NULL,name_ar text NOT NULL,name_en text NOT NULL,active boolean NOT NULL DEFAULT true,priority integer NOT NULL DEFAULT 100,category text NOT NULL,payload_cipher text NOT NULL,UNIQUE(tenant_id,code),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_journals(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,number bigint NOT NULL,source_key text NOT NULL,effective_on date NOT NULL,currency char(3) NOT NULL,status text NOT NULL CHECK(status IN('Draft','Posted')),reversal_of uuid,payload_cipher text NOT NULL,approved_by uuid,posted_at timestamptz,UNIQUE(tenant_id,company_id,source_key),UNIQUE(tenant_id,number),CHECK((status='Posted')=(approved_by IS NOT NULL AND posted_at IS NOT NULL)),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,reversal_of)REFERENCES ab.finance_journals(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_periods(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,month date NOT NULL CHECK(extract(day from month)=1),closed_by uuid NOT NULL,report_cipher text NOT NULL,UNIQUE(tenant_id,company_id,month),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,closed_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_invoice_links(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,invoice_id uuid NOT NULL,item_id uuid NOT NULL,issued_on date NOT NULL,source_key text NOT NULL,UNIQUE(tenant_id,invoice_id),UNIQUE(tenant_id,company_id,source_key),FOREIGN KEY(tenant_id,company_id,invoice_id)REFERENCES ab.vehicle_invoices(tenant_id,company_id,id),FOREIGN KEY(tenant_id,item_id)REFERENCES ab.finance_items(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_receipt_batches(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,customer_id uuid NOT NULL,vehicle_id uuid,method text NOT NULL CHECK(method IN('cash','cheque','transfer')),currency char(3) NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),received_on date NOT NULL,cheque_id uuid,operation_id uuid,payload_cipher text NOT NULL,UNIQUE(tenant_id,operation_id),UNIQUE(tenant_id,cheque_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,cheque_id)REFERENCES ab.finance_cheques(tenant_id,id),FOREIGN KEY(tenant_id,operation_id)REFERENCES ab.finance_operations(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_allocation_reversals(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,allocation_id uuid NOT NULL,reason text NOT NULL,UNIQUE(tenant_id,allocation_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,allocation_id)REFERENCES ab.vehicle_allocations(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_custody_moves(effective_on date NOT NULL DEFAULT (timezone('Asia/Dubai',now()))::date,id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,receipt_id uuid NOT NULL,holder_id uuid NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount<>0),currency char(3) NOT NULL,source_key text NOT NULL,UNIQUE(tenant_id,source_key),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,receipt_id)REFERENCES ab.finance_receipts(tenant_id,id),FOREIGN KEY(tenant_id,holder_id)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_custody_routes(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,sender_id uuid NOT NULL,receiver_id uuid NOT NULL,effective_on date NOT NULL,until_on date,CHECK(sender_id<>receiver_id),CHECK(until_on IS NULL OR until_on>=effective_on),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,sender_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,receiver_id)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_custody_transfers(kind text NOT NULL DEFAULT 'cash'CHECK(kind IN('cash','cheque')),id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,sender_id uuid NOT NULL,receiver_id uuid NOT NULL,currency char(3) NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),actual numeric(21,3),status text NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Accepted','Rejected')),payload_cipher text NOT NULL,received_at timestamptz,CHECK(sender_id<>receiver_id),CHECK(actual IS NULL OR actual BETWEEN 0 AND amount),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,sender_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,receiver_id)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_deposits(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,holder_id uuid NOT NULL,bank_account_id uuid NOT NULL,currency char(3) NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),confirmed numeric(21,3),effective_on date NOT NULL,status text NOT NULL DEFAULT 'Review' CHECK(status IN('Review','Confirmed','Rejected')),document_version_id uuid NOT NULL,operation_id uuid,verified_by uuid,payload_cipher text NOT NULL,CHECK(confirmed IS NULL OR confirmed BETWEEN 0 AND amount),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,company_id,bank_account_id)REFERENCES ab.bank_accounts(tenant_id,company_id,id),FOREIGN KEY(tenant_id,holder_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,document_version_id)REFERENCES ab.document_versions(tenant_id,id),FOREIGN KEY(tenant_id,operation_id)REFERENCES ab.finance_operations(tenant_id,id),FOREIGN KEY(tenant_id,verified_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_funds(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,name text NOT NULL,kind text NOT NULL CHECK(kind IN('cash','petty')),holder_id uuid NOT NULL,chart_id uuid NOT NULL,currency char(3) NOT NULL,ceiling numeric(21,3) NOT NULL DEFAULT 1000 CHECK(ceiling>0),threshold numeric(21,3) NOT NULL DEFAULT 200 CHECK(threshold>=0 AND threshold<=ceiling),active boolean NOT NULL DEFAULT true,UNIQUE(tenant_id,chart_id),FOREIGN KEY(tenant_id,company_id,chart_id)REFERENCES ab.finance_chart(tenant_id,company_id,id),FOREIGN KEY(tenant_id,holder_id)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_vouchers(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,item_id uuid NOT NULL,customer_id uuid,number bigint NOT NULL,source_key text NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL,issued_on date NOT NULL,status text NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Approved','Paid','Cancelled')),bank_account_id uuid,cheque_id uuid,operation_id uuid,approved_by uuid,approved_at timestamptz,payload_cipher text NOT NULL,revision integer NOT NULL DEFAULT 1,UNIQUE(tenant_id,company_id,source_key),UNIQUE(tenant_id,number),UNIQUE(tenant_id,cheque_id),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,item_id)REFERENCES ab.finance_items(tenant_id,id),FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,company_id,bank_account_id)REFERENCES ab.bank_accounts(tenant_id,company_id,id),FOREIGN KEY(tenant_id,cheque_id)REFERENCES ab.finance_cheques(tenant_id,id),FOREIGN KEY(tenant_id,operation_id)REFERENCES ab.finance_operations(tenant_id,id),FOREIGN KEY(tenant_id,approved_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_approval_batches(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,actor_id uuid NOT NULL,digest text NOT NULL,payload_cipher text NOT NULL,expires_at timestamptz NOT NULL,used_at timestamptz,FOREIGN KEY(tenant_id,actor_id)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_work_amounts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,customer_id uuid NOT NULL,batch_id uuid NOT NULL,invoice_id uuid NOT NULL,voucher_id uuid NOT NULL,UNIQUE(tenant_id,batch_id),UNIQUE(tenant_id,invoice_id),UNIQUE(tenant_id,voucher_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,batch_id)REFERENCES ab.finance_receipt_batches(tenant_id,id),FOREIGN KEY(tenant_id,invoice_id)REFERENCES ab.vehicle_invoices(tenant_id,id),FOREIGN KEY(tenant_id,voucher_id)REFERENCES ab.finance_vouchers(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_cards(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,holder_id uuid NOT NULL,bank_name text NOT NULL,last_four char(4) NOT NULL CHECK(last_four~'^[0-9]{4}$'),name text NOT NULL,currency char(3) NOT NULL,due_day integer NOT NULL CHECK(due_day BETWEEN 1 AND 28),liability_id uuid NOT NULL,active boolean NOT NULL DEFAULT true,FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,holder_id)REFERENCES ab.users(tenant_id,id),FOREIGN KEY(tenant_id,liability_id)REFERENCES ab.finance_chart(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_card_charges(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,card_id uuid NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL,paid_on date NOT NULL,reference text NOT NULL,payload_cipher text NOT NULL,UNIQUE(tenant_id,card_id,reference),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,card_id)REFERENCES ab.finance_cards(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_card_splits(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,charge_id uuid NOT NULL,item_id uuid NOT NULL,customer_id uuid,vehicle_id uuid,amount numeric(21,3) NOT NULL CHECK(amount>0),invoice_id uuid,completed_by uuid,completed_at timestamptz,FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,charge_id)REFERENCES ab.finance_card_charges(tenant_id,id),FOREIGN KEY(tenant_id,item_id)REFERENCES ab.finance_items(tenant_id,id),FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,invoice_id)REFERENCES ab.vehicle_invoices(tenant_id,company_id,id),FOREIGN KEY(tenant_id,completed_by)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_card_matches(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,statement_id uuid NOT NULL,line_id uuid NOT NULL,charge_id uuid NOT NULL,UNIQUE(tenant_id,line_id),UNIQUE(tenant_id,charge_id),FOREIGN KEY(tenant_id,statement_id)REFERENCES ab.finance_statements(tenant_id,id),FOREIGN KEY(tenant_id,line_id)REFERENCES ab.finance_statement_lines(tenant_id,id),FOREIGN KEY(tenant_id,charge_id)REFERENCES ab.finance_card_charges(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_card_settlements(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,card_id uuid NOT NULL,month date NOT NULL,voucher_id uuid NOT NULL,amount numeric(21,3) NOT NULL CHECK(amount>0),UNIQUE(tenant_id,card_id,month,company_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,card_id)REFERENCES ab.finance_cards(tenant_id,id),FOREIGN KEY(tenant_id,voucher_id)REFERENCES ab.finance_vouchers(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_intercompany(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,to_company_id uuid NOT NULL,to_bank_account_id uuid NOT NULL,voucher_id uuid NOT NULL,receipt_operation_id uuid,state text NOT NULL DEFAULT 'Pending' CHECK(state IN('Pending','Paid','Deposited')),payload_cipher text NOT NULL,CHECK(company_id<>to_company_id),UNIQUE(tenant_id,voucher_id),UNIQUE(tenant_id,receipt_operation_id),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,to_company_id,to_bank_account_id)REFERENCES ab.bank_accounts(tenant_id,company_id,id),FOREIGN KEY(tenant_id,voucher_id)REFERENCES ab.finance_vouchers(tenant_id,id),FOREIGN KEY(tenant_id,receipt_operation_id)REFERENCES ab.finance_operations(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_invoice_imports(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,source_hash text NOT NULL,payload_cipher text NOT NULL,status text NOT NULL DEFAULT 'Preview' CHECK(status IN('Preview','Completed')),UNIQUE(tenant_id,company_id,source_hash),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_kpi_facts(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,company_id uuid NOT NULL,employee_id uuid NOT NULL,kind text NOT NULL,source_key text NOT NULL,amount numeric(21,3),payload_cipher text NOT NULL,UNIQUE(tenant_id,source_key),FOREIGN KEY(tenant_id,company_id)REFERENCES ab.companies(tenant_id,id),FOREIGN KEY(tenant_id,employee_id)REFERENCES ab.users(tenant_id,id),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));
CREATE TABLE ab.finance_group_closings(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES ab.organizations,month date NOT NULL,companies uuid[] NOT NULL,payload_cipher text NOT NULL,UNIQUE(tenant_id,month),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,created_by)REFERENCES ab.users(tenant_id,id));

ALTER TABLE ab.finance_chart ADD COLUMN definition_id uuid,ADD COLUMN active boolean NOT NULL DEFAULT true,ADD CONSTRAINT finance_definition_fk FOREIGN KEY(tenant_id,definition_id)REFERENCES ab.finance_accounts(tenant_id,id);
ALTER TABLE ab.vehicle_invoices ALTER COLUMN vehicle_id DROP NOT NULL;
ALTER TABLE ab.vehicle_invoices DROP CONSTRAINT vehicle_invoices_kind_check;
ALTER TABLE ab.vehicle_invoices ADD CONSTRAINT vehicle_invoices_kind_check CHECK(kind IN('finance','service','insurance','gps','salik','fine','admin','circular','recovery','financial'));
ALTER TABLE ab.finance_entries ALTER COLUMN operation_id DROP NOT NULL,ADD COLUMN journal_id uuid,ADD CONSTRAINT journal_fk FOREIGN KEY(tenant_id,journal_id)REFERENCES ab.finance_journals(tenant_id,id),ADD CONSTRAINT journal_source CHECK((operation_id IS NULL)<>(journal_id IS NULL));
ALTER TABLE ab.finance_receipts ADD COLUMN item_id uuid,ADD COLUMN batch_id uuid,ADD COLUMN customer_id uuid,ADD COLUMN vehicle_id uuid,ADD COLUMN receipt_number bigint,ADD COLUMN received_on date,ADD COLUMN payment_state text CHECK(payment_state IN('Pending','Cleared','Returned')),ADD COLUMN payload_cipher text,ADD CONSTRAINT receipt_item_fk FOREIGN KEY(tenant_id,item_id)REFERENCES ab.finance_items(tenant_id,id),ADD CONSTRAINT receipt_batch_fk FOREIGN KEY(tenant_id,batch_id)REFERENCES ab.finance_receipt_batches(tenant_id,id),ADD CONSTRAINT receipt_customer_fk FOREIGN KEY(tenant_id,customer_id)REFERENCES ab.customers(tenant_id,id),ADD CONSTRAINT receipt_vehicle_fk FOREIGN KEY(tenant_id,company_id,vehicle_id)REFERENCES ab.vehicles(tenant_id,company_id,id);
ALTER TABLE ab.finance_receipts DROP CONSTRAINT finance_receipts_kind_check;
ALTER TABLE ab.finance_receipts ADD CONSTRAINT finance_receipts_kind_check CHECK(kind IN('cash','cheque','transfer'));
ALTER TABLE ab.finance_receipts DROP CONSTRAINT finance_receipts_tenant_id_cheque_id_key;
CREATE UNIQUE INDEX legacy_receipt_cheque ON ab.finance_receipts(tenant_id,cheque_id)WHERE item_id IS NULL;
CREATE UNIQUE INDEX financial_receipt_number ON ab.finance_receipts(tenant_id,receipt_number)WHERE receipt_number IS NOT NULL;
ALTER TABLE ab.vehicle_allocations ALTER COLUMN operation_id DROP NOT NULL,ADD COLUMN receipt_id uuid,ADD CONSTRAINT receipt_allocation_fk FOREIGN KEY(tenant_id,receipt_id)REFERENCES ab.finance_receipts(tenant_id,id),ADD CONSTRAINT allocation_source CHECK((operation_id IS NULL)<>(receipt_id IS NULL));
CREATE UNIQUE INDEX receipt_invoice_once ON ab.vehicle_allocations(tenant_id,receipt_id,invoice_id)WHERE receipt_id IS NOT NULL;
ALTER TABLE ab.finance_statements ALTER COLUMN bank_account_id DROP NOT NULL,ADD COLUMN card_id uuid,ADD CONSTRAINT card_statement_fk FOREIGN KEY(tenant_id,card_id)REFERENCES ab.finance_cards(tenant_id,id),ADD CONSTRAINT statement_source CHECK((card_id IS NULL)<>(bank_account_id IS NULL));
CREATE UNIQUE INDEX card_statement_source ON ab.finance_statements(tenant_id,card_id,source_hash)WHERE card_id IS NOT NULL;
CREATE TRIGGER financial_events_immutable BEFORE UPDATE OR DELETE ON ab.finance_events FOR EACH ROW EXECUTE FUNCTION ab.vehicle_immutable();
CREATE FUNCTION ab.financial_journal_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='Posted' THEN RAISE EXCEPTION 'posted journal immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER journal_immutable BEFORE UPDATE OR DELETE ON ab.finance_journals FOR EACH ROW EXECUTE FUNCTION ab.financial_journal_guard();
CREATE OR REPLACE FUNCTION ab.finance_entry_draft_only() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.journal_id IS NOT NULL THEN
 IF NOT EXISTS(SELECT 1 FROM ab.finance_journals j JOIN ab.finance_chart a ON a.tenant_id=j.tenant_id AND a.id=NEW.chart_id WHERE j.tenant_id=NEW.tenant_id AND j.id=NEW.journal_id AND j.status='Draft' AND j.company_id=NEW.company_id AND j.currency=NEW.currency AND a.company_id=NEW.company_id AND a.currency=NEW.currency AND a.active AND a.bank_account_id IS NOT DISTINCT FROM NEW.bank_account_id)THEN RAISE EXCEPTION 'invalid journal line' USING ERRCODE='23514';END IF;
 ELSE
 IF NOT EXISTS(SELECT 1 FROM ab.finance_operations o JOIN ab.finance_chart a ON a.tenant_id=o.tenant_id AND a.id=NEW.chart_id WHERE o.tenant_id=NEW.tenant_id AND o.id=NEW.operation_id AND o.status='Draft' AND a.company_id=NEW.company_id AND a.currency=NEW.currency AND o.currency=NEW.currency AND a.bank_account_id IS NOT DISTINCT FROM NEW.bank_account_id)THEN RAISE EXCEPTION 'posted entries append protected' USING ERRCODE='23514';END IF;
 END IF;RETURN NEW;END $$;
CREATE FUNCTION ab.financial_journal_balance()RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status='Posted' AND (NOT EXISTS(SELECT 1 FROM ab.finance_entries WHERE journal_id=NEW.id AND tenant_id=NEW.tenant_id)OR EXISTS(SELECT 1 FROM ab.finance_entries WHERE journal_id=NEW.id AND tenant_id=NEW.tenant_id GROUP BY company_id,currency HAVING sum(debit)<>sum(credit) OR count(*)<2))THEN RAISE EXCEPTION 'unbalanced journal' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER journal_balanced AFTER INSERT OR UPDATE ON ab.finance_journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ab.financial_journal_balance();
CREATE FUNCTION ab.financial_chart_guard()RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF (OLD.kind,OLD.company_id,OLD.currency,OLD.definition_id,OLD.bank_account_id)IS DISTINCT FROM(NEW.kind,NEW.company_id,NEW.currency,NEW.definition_id,NEW.bank_account_id)AND EXISTS(SELECT 1 FROM ab.finance_entries WHERE chart_id=OLD.id)THEN RAISE EXCEPTION 'used account nature immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER used_chart_nature BEFORE UPDATE ON ab.finance_chart FOR EACH ROW EXECUTE FUNCTION ab.financial_chart_guard();
GRANT UPDATE ON ab.finance_chart TO ab_runtime;
CREATE FUNCTION ab.financial_account_guard()RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF(OLD.kind,OLD.parent_id,OLD.eliminate,OLD.cash_flow)IS DISTINCT FROM(NEW.kind,NEW.parent_id,NEW.eliminate,NEW.cash_flow)AND EXISTS(SELECT 1 FROM ab.finance_chart c JOIN ab.finance_entries e ON e.chart_id=c.id WHERE c.definition_id=OLD.id)THEN RAISE EXCEPTION 'used account nature immutable' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER used_account_nature BEFORE UPDATE ON ab.finance_accounts FOR EACH ROW EXECUTE FUNCTION ab.financial_account_guard();
CREATE FUNCTION ab.financial_allocation_total(target uuid)RETURNS numeric LANGUAGE sql STABLE AS $$SELECT coalesce(sum(a.amount),0)FROM ab.vehicle_allocations a WHERE a.invoice_id=target AND a.tenant_id=ab.tenant()AND NOT EXISTS(SELECT 1 FROM ab.finance_allocation_reversals r WHERE r.allocation_id=a.id AND r.tenant_id=a.tenant_id)$$;
CREATE OR REPLACE FUNCTION ab.vehicle_allocation_valid()RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE bill ab.vehicle_invoices;op ab.finance_operations;r ab.finance_receipts; BEGIN
 SELECT * INTO bill FROM ab.vehicle_invoices WHERE tenant_id=NEW.tenant_id AND id=NEW.invoice_id;
 IF NEW.receipt_id IS NULL THEN
 SELECT * INTO op FROM ab.finance_operations WHERE tenant_id=NEW.tenant_id AND id=NEW.operation_id;IF EXISTS(SELECT 1 FROM ab.finance_receipt_batches b WHERE b.tenant_id=NEW.tenant_id AND(b.operation_id=op.id OR b.cheque_id=op.cheque_id))THEN RAISE EXCEPTION 'financial receipt allocated only through batch' USING ERRCODE='23514';END IF;
 IF op.status IS DISTINCT FROM 'Approved' OR op.kind IS DISTINCT FROM 'receipt' OR op.company_id IS DISTINCT FROM bill.company_id OR op.currency IS DISTINCT FROM bill.currency OR(op.integration_refs->>'clientReference')IS DISTINCT FROM bill.customer_id::text OR(op.integration_refs->>'vehicleReference')IS DISTINCT FROM bill.vehicle_id::text THEN RAISE EXCEPTION 'invalid receipt allocation' USING ERRCODE='23514';END IF;
 IF(SELECT coalesce(sum(amount),0)FROM ab.vehicle_allocations a WHERE a.tenant_id=NEW.tenant_id AND a.operation_id=NEW.operation_id AND NOT EXISTS(SELECT 1 FROM ab.finance_allocation_reversals x WHERE x.allocation_id=a.id))>op.amount THEN RAISE EXCEPTION 'receipt overallocated' USING ERRCODE='23514';END IF;
 ELSE
 SELECT * INTO r FROM ab.finance_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.receipt_id;
 IF r.payment_state IS DISTINCT FROM 'Cleared' OR r.company_id IS DISTINCT FROM bill.company_id OR r.currency IS DISTINCT FROM bill.currency OR r.customer_id IS DISTINCT FROM bill.customer_id OR r.vehicle_id IS DISTINCT FROM bill.vehicle_id OR NOT EXISTS(SELECT 1 FROM ab.finance_invoice_links l WHERE l.invoice_id=bill.id AND l.item_id=r.item_id AND l.tenant_id=r.tenant_id) THEN RAISE EXCEPTION 'invalid item receipt allocation' USING ERRCODE='23514';END IF;
 IF(SELECT coalesce(sum(amount),0)FROM ab.vehicle_allocations a WHERE a.receipt_id=r.id AND a.tenant_id=r.tenant_id AND NOT EXISTS(SELECT 1 FROM ab.finance_allocation_reversals x WHERE x.allocation_id=a.id))>r.amount THEN RAISE EXCEPTION 'receipt overallocated' USING ERRCODE='23514';END IF;
 END IF;
 IF ab.financial_allocation_total(bill.id)+(SELECT coalesce(sum(amount),0)FROM ab.vehicle_invoice_adjustments WHERE tenant_id=NEW.tenant_id AND invoice_id=bill.id AND kind<>'writeoff')>bill.amount THEN RAISE EXCEPTION 'invoice overallocated' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE OR REPLACE FUNCTION ab.vehicle_credit_valid()RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF ab.financial_allocation_total(NEW.invoice_id)+(SELECT coalesce(sum(amount),0)FROM ab.vehicle_invoice_adjustments WHERE tenant_id=NEW.tenant_id AND invoice_id=NEW.invoice_id AND(kind<>'writeoff'OR NEW.kind='writeoff'))>(SELECT amount FROM ab.vehicle_invoices WHERE tenant_id=NEW.tenant_id AND id=NEW.invoice_id)THEN RAISE EXCEPTION 'credit exceeds invoice' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE FUNCTION ab.financial_open_period()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE co uuid;on_date date;BEGIN co=NEW.company_id;on_date=COALESCE((to_jsonb(NEW)->>'effective_on')::date,(to_jsonb(NEW)->>'received_on')::date,(to_jsonb(NEW)->>'issued_on')::date,(timezone('Asia/Dubai',now()))::date);IF EXISTS(SELECT 1 FROM ab.finance_periods p WHERE p.tenant_id=NEW.tenant_id AND p.company_id=co AND p.month=date_trunc('month',on_date)::date)THEN RAISE EXCEPTION 'financial period closed' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
