CREATE INDEX financial_journal_date ON ab.finance_journals(tenant_id,company_id,effective_on);
CREATE INDEX financial_custody_holder ON ab.finance_custody_moves(tenant_id,company_id,holder_id,receipt_id);
CREATE FUNCTION ab.financial_receipt_guard()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF OLD.item_id IS NOT NULL AND(OLD.tenant_id,OLD.company_id,OLD.holder_id,OLD.amount,OLD.currency,OLD.kind,OLD.cheque_id,OLD.item_id,OLD.batch_id,OLD.customer_id,OLD.vehicle_id,OLD.receipt_number,OLD.received_on,OLD.payload_cipher)IS DISTINCT FROM(NEW.tenant_id,NEW.company_id,NEW.holder_id,NEW.amount,NEW.currency,NEW.kind,NEW.cheque_id,NEW.item_id,NEW.batch_id,NEW.customer_id,NEW.vehicle_id,NEW.receipt_number,NEW.received_on,NEW.payload_cipher)THEN RAISE EXCEPTION 'immutable financial receipt' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER financial_receipt_immutable BEFORE UPDATE ON ab.finance_receipts FOR EACH ROW EXECUTE FUNCTION ab.financial_receipt_guard();
CREATE FUNCTION ab.financial_custody_valid()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE r ab.finance_receipts;BEGIN SELECT * INTO r FROM ab.finance_receipts WHERE id=NEW.receipt_id AND tenant_id=NEW.tenant_id;IF r.item_id IS NULL OR r.kind NOT IN('cash','cheque') OR NEW.company_id IS DISTINCT FROM r.company_id OR NEW.currency IS DISTINCT FROM r.currency OR EXISTS(SELECT 1 FROM ab.finance_custody_moves WHERE tenant_id=NEW.tenant_id AND receipt_id=NEW.receipt_id GROUP BY holder_id HAVING sum(amount)<0)OR(SELECT sum(amount)FROM ab.finance_custody_moves WHERE tenant_id=NEW.tenant_id AND receipt_id=NEW.receipt_id)>r.amount THEN RAISE EXCEPTION 'invalid custody balance' USING ERRCODE='23514';END IF;RETURN NULL;END $$;
CREATE CONSTRAINT TRIGGER custody_balanced AFTER INSERT ON ab.finance_custody_moves DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION ab.financial_custody_valid();
REVOKE ALL ON FUNCTION ab.financial_receipt_guard(),ab.financial_custody_valid()FROM PUBLIC;
